"""Loopback-only viewer of frames generated by the bounded native MUF rehost.

The browser displays a PNG framebuffer; it does not draw television widgets.
Keys only supply test state to the declared emulated service boundaries.
"""
from __future__ import annotations
from collections import OrderedDict
import argparse
import gc
import hashlib
from http.server import BaseHTTPRequestHandler, HTTPServer
import io
import json
from pathlib import Path
from urllib.parse import parse_qs, quote, unquote, urlsplit

from native_frame_rehost import render, render_numeric, render_mute_badge

ROOT = Path(__file__).resolve().parents[1]
HTML = ROOT/'native-ui/frame-viewer/index.html'
CACHE = OrderedDict()
PREVIEW=ROOT/'ui-preview'
PREVIEW_MIMES={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8',
               '.css':'text/css; charset=utf-8','.svg':'image/svg+xml','.png':'image/png','.json':'application/json; charset=utf-8'}

def preview_file(path):
    """Serve only explicit UI files and pinned public graphic/font inputs."""
    from native_frame_rehost import SOURCE, V6_OVERLAY, FONT_SHA, V4_ICON_SHA
    assets={
        'native-fonts/DINPro-CondMedium.otf':(SOURCE/'08_APP/rc/font/DINPro-CondMedium.otf',FONT_SHA[0x4ae],'font/otf'),
        'native-fonts/DejaVuSans.ttf':(SOURCE/'08_APP/rc/rc/DejaVuSans.ttf',FONT_SHA[0x4b0],'font/ttf'),
        'native-assets/volume-background.png':(V6_OVERLAY/'08_APP/rc/ARimages/Common/popups/volumeControl/bg.png','db95b29b413e60c2e7d6a9de3497cecd417c3edf5dc3224820e8da250b32b7f6','image/png'),
        'native-assets/volume-speaker.png':(V6_OVERLAY/'08_APP/rc/ARimages/Grundig/volume/volume_icon.png',V4_ICON_SHA[682],'image/png'),
        'native-assets/volume-mute.png':(V6_OVERLAY/'08_APP/rc/ARimages/Grundig/volume/mute_icon.png',V4_ICON_SHA[680],'image/png'),
    }
    relative=unquote(path[len('/preview/'):]) or 'index.html'
    if relative in assets:
        source,expected,mime=assets[relative]
        if source.is_symlink() or not source.resolve().is_relative_to(ROOT.resolve()):raise ValueError('Invalid pinned asset path')
        raw=source.read_bytes()
        if hashlib.sha256(raw).hexdigest()!=expected:raise ValueError('Pinned preview asset mismatch')
        return raw,mime
    if '\\' in relative or ':' in relative or any(not p or p.startswith('.') for p in relative.split('/')) or relative.split('/')[0]=='tests':
        raise ValueError('Invalid static UI path')
    target=PREVIEW/relative
    if not target.resolve().is_relative_to(PREVIEW.resolve()) or not target.is_file() or target.suffix not in PREVIEW_MIMES:
        raise ValueError('Unknown UI file')
    cursor=target
    while cursor!=PREVIEW:
        if cursor.is_symlink() or (hasattr(cursor,'is_junction') and cursor.is_junction()):raise ValueError('Aliased UI file')
        cursor=cursor.parent
    if target.stat().st_nlink!=1:raise ValueError('Hardlinked UI file')
    return target.read_bytes(),PREVIEW_MIMES[target.suffix]


def frame_bytes(query):
    values = parse_qs(query, strict_parsing=True)
    if set(values)-{'variant', 'scene', 'volume', 'mute', 'digits', 'elapsed_ms'}:
        raise ValueError('Unknown parameter')
    if any(len(v) != 1 for v in values.values()):
        raise ValueError('Duplicate parameter')
    variant = values.get('variant', ['v7.9-tv'])[0]
    scene = values.get('scene', ['volume'])[0]
    volume = int(values.get('volume', ['35'])[0])
    mute = values.get('mute', ['0'])[0]
    digits = values.get('digits', ['123'])[0]
    elapsed_ms = int(values.get('elapsed_ms', ['0'])[0])
    if not 0<=elapsed_ms<=10000 or (elapsed_ms and (variant!='v7.6-tv' or scene!='numeric')):
        raise ValueError('Invalid bounded countdown input')
    if variant not in ('original', 'v3', 'v4', 'v5', 'v6', 'v7', 'v7-tv', 'v7.1-tv', 'v7.4-tv', 'v7.5-tv', 'v7.6-tv', 'v7.7-tv','v7.9-tv') or scene not in ('volume', 'numeric', 'mute', 'mute-key', 'timeout') or not 0 <= volume <= 100 or mute not in ('0', '1'):
        raise ValueError('Invalid bounded test input')
    if scene in ('mute-key','timeout') and variant not in ('v7.7-tv','v7.9-tv'):
        raise ValueError('Native lifecycle scenes require V7.7')
    if not digits.isascii() or not digits.isdigit() or not 1 <= len(digits) <= (4 if variant in ('v7.5-tv','v7.6-tv','v7.7-tv','v7.9-tv') else 5):
        raise ValueError('Expected 1..5 ASCII digits')
    key = (variant, scene, volume, mute, digits, elapsed_ms)
    if key in CACHE:
        CACHE.move_to_end(key)
        return CACHE[key]
    if scene in ('mute-key','timeout'):
        from native_mute_v77_rehost import render_flow
        image,evidence=render_flow(variant,scene,volume,mute=='1')
    else:
        image, evidence = render(variant, volume, mute == '1') if scene == 'volume' else render_mute_badge(variant) if scene=='mute' else render_numeric(variant, digits, elapsed_ms=elapsed_ms)
    output = io.BytesIO()
    image.save(output, format='PNG')
    channel=evidence.get('channel_resolution')
    if channel and channel.get('native_name_bridge_installed'):
        channel={key:channel[key] for key in ('digits','number','matched','name','native_name_bridge_installed','data_source','device_database')}
    panel_timeout_ms=None
    for timer in evidence.get('native_volume_state',{}).get('state',{}).get('timers',[]):
        if timer['name']=='SetTimer' and timer['args'][1:3]==[0,1]:panel_timeout_ms=timer['args'][0]
    for timer in evidence.get('native_lifecycle',{}).get('timers',[]):
        if timer[0]=='SetTimer' and timer[2:4]==[0,1]:panel_timeout_ms=timer[1]
    metadata = {'variant': variant, 'scene': scene, 'volume': volume, 'mute': evidence.get('mute',mute == '1'), 'digits': digits,
                'channel_resolution': channel,
                'panel_timeout_ms':panel_timeout_ms,
                'native_lifecycle':evidence.get('native_lifecycle'),
                'countdown':evidence.get('native_name_bridge',{}).get('countdown') if evidence.get('native_name_bridge') else None,
                'native_name_bridge': ({key:evidence['native_name_bridge'][key] for key in ('native_name_bridge_installed','data_source','device_database','helper_inputs')} if evidence.get('native_name_bridge') else None),
                'specimen_layout': evidence.get('specimen_layout'),
                'full_native_menu_executed':False,
                'surface_geometry':evidence.get('surface_geometry'),
                'panel_style':evidence.get('panel_style'),
                'progress_fill_color':evidence.get('progress_fill_color'),
                'lifecycle_executed':evidence.get('lifecycle_executed'),
                'lifecycle_provenance':evidence.get('lifecycle_provenance'),
                'omitted':evidence.get('omitted'),
                'verified_pins':evidence.get('verified_pins'),
                'native_instructions': {k: v['unique_executed_instructions'] for k, v in evidence['native_functions'].items()},
                'boundaries': 'Bounded MUF instructions, Pillow framebuffer, modeled parent clipping and mocked services; no running TV, tuner or GOP driver'}
    CACHE[key] = (output.getvalue(), json.dumps(metadata).encode('utf-8'))
    while len(CACHE) > 24:
        CACHE.popitem(last=False)
    del image, evidence
    gc.collect()
    return CACHE[key]


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        # Protect this local computational API from browser cross-origin access.
        host = self.headers.get('Host', '')
        expected = f'127.0.0.1:{self.server.server_port}'
        origin = self.headers.get('Origin')
        if host != expected or (origin and origin != 'http://'+expected):
            self.send_error(403)
            return
        url = urlsplit(self.path)
        channel_header=None
        native_ui_header=None
        preview_response=False
        if len(url.query) > 256:
            self.send_error(400)
            return
        if url.path=='/favicon.ico':
            self.send_response(204);self.end_headers();return
        if url.path=='/preview':
            self.send_response(302);self.send_header('Location','/preview/?menu=1');self.end_headers();return
        if url.path.startswith('/preview/'):
            try:payload,mime=preview_file(url.path)
            except (ValueError,OSError):self.send_error(404);return
            preview_response=True
        elif url.path in ('/', '/index.html'):
            payload, mime = HTML.read_bytes(), 'text/html; charset=utf-8'
        elif url.path in ('/frame.png', '/frame.json'):
            try:
                png, metadata = frame_bytes(url.query)
            except (ValueError, TypeError):
                self.send_error(400, 'Invalid test input')
                return
            except Exception:
                self.send_error(500, 'Native rehost failed; no substitute frame generated')
                return
            payload, mime = (png, 'image/png') if url.path.endswith('.png') else (metadata, 'application/json')
            decoded=json.loads(metadata)
            channel=decoded.get('channel_resolution')
            if decoded['variant'] in ('v7.7-tv','v7.9-tv'):
                native_ui_header=quote(json.dumps(dict(muted=decoded['mute'],panel_timeout_ms=decoded.get('panel_timeout_ms'),panel_open=decoded.get('native_lifecycle',{}).get('panel_open') if decoded.get('native_lifecycle') else decoded['scene']=='volume',badge_visible=decoded.get('native_lifecycle',{}).get('badge_visible') if decoded.get('native_lifecycle') else decoded['scene']=='mute')),safe='')
            if channel is not None:
                channel_header=quote(json.dumps(channel,ensure_ascii=False),safe='')
        else:
            self.send_error(404)
            return
        self.send_response(200)
        self.send_header('Content-Type', mime)
        self.send_header('Content-Length', str(len(payload)))
        self.send_header('Cache-Control', 'no-store')
        if native_ui_header is not None:
            self.send_header('X-Native-UI-State',native_ui_header)
        if channel_header is not None:
            self.send_header('X-Channel-Resolution',channel_header)
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Cross-Origin-Resource-Policy', 'same-origin')
        csp=("default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'" if preview_response else
             "default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' blob:; connect-src 'self'")
        self.send_header('Content-Security-Policy',csp)
        self.end_headers()
        self.wfile.write(payload)

    def log_message(self, format, *args):
        pass


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--port', type=int, default=4174)
    args = parser.parse_args()
    if not 1024 <= args.port <= 65535:
        parser.error('Choose an unprivileged port')
    server = HTTPServer(('127.0.0.1', args.port), Handler)
    print(f'Native MUF framebuffer viewer: http://127.0.0.1:{args.port}', flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == '__main__':
    main()
